/// One entry of a table, decoded.
#[must_use]
pub fn cell(table: &[[u32; LON_TABLE_SIZE]; LAT_TABLE_SIZE], lat: usize, lon: usize) -> f32 {
    match table.get(lat).and_then(|row| row.get(lon)) {
        Some(&b) => f32::from_bits(b),
        None => 0.0,
    }
}
